package br.com.onda;
import android.app.*;import android.net.Uri;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;import java.util.concurrent.*;
/** Inline form owned and dismissed by the calling screen, never pauses playback. */
@androidx.media3.common.util.UnstableApi
final class MemoryMark {
 static AlertDialog show(Activity activity,Uri uri,String title,String kind,int page,long position,long limit){
  if(uri==null||!("content".equals(uri.getScheme())||"file".equals(uri.getScheme()))||limit<=0||!java.util.Arrays.asList("manual_audio","manual_video","manual_pdf").contains(kind)){Toast.makeText(activity,"Abra um arquivo local com duração ou página disponível.",Toast.LENGTH_LONG).show();return null;}
  ExecutorService worker=Executors.newSingleThreadExecutor();Handler main=new Handler(Looper.getMainLooper());LinearLayout box=new LinearLayout(activity);box.setOrientation(LinearLayout.VERTICAL);int pad=Ui.dp(activity,16);box.setPadding(pad,pad,pad,pad);box.addView(Ui.text(activity,(title==null?"Arquivo":title)+(page>=0?" • página "+(page+1):""),14,Ui.TEXT));box.addView(Ui.text(activity,"Dê um nome para reencontrar este ponto na Memória Multimídia. Os horários ficam fixados ao abrir este formulário.",13,Ui.MUTED));EditText label=new EditText(activity);label.setHint(page>=0?"Ex.: explicação sobre juros":"Ex.: solo de guitarra");label.setTextColor(Ui.TEXT);label.setContentDescription("Nome da marcação na memória");label.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(500)});label.setMinLines(1);label.setMaxLines(3);box.addView(label,new LinearLayout.LayoutParams(-1,-2));EditText from=new EditText(activity),to=new EditText(activity);long start=MemoryNote.start(position,limit);from.setText(ChapterEdits.format(start));to.setText(ChapterEdits.format(MemoryNote.end(start,limit)));from.setContentDescription("Início da marcação");to.setContentDescription("Fim da marcação");for(EditText time:new EditText[]{from,to}){time.setSingleLine(true);time.setTextColor(Ui.TEXT);time.setInputType(InputType.TYPE_CLASS_TEXT);time.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(24)});}if(page<0){box.addView(Ui.text(activity,"Início • minutos:segundos.milissegundos",12,Ui.MUTED));box.addView(from,new LinearLayout.LayoutParams(-1,-2));box.addView(Ui.text(activity,"Fim • minutos:segundos.milissegundos",12,Ui.MUTED));box.addView(to,new LinearLayout.LayoutParams(-1,-2));}TextView status=Ui.text(activity,"A marcação não altera o arquivo original e fica nos trechos favoritos.",12,Ui.MUTED);status.setContentDescription("Estado da marcação na memória");box.addView(status);ScrollView scroll=new ScrollView(activity);scroll.addView(box);
  AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("Marcar na memória").setView(scroll).setPositiveButton("Salvar",null).setNegativeButton("Cancelar",null).create();dialog.setOnDismissListener(d->worker.shutdown());dialog.show();android.content.Context app=activity.getApplicationContext();java.lang.ref.WeakReference<Activity> host=new java.lang.ref.WeakReference<>(activity);java.lang.ref.WeakReference<AlertDialog> weak=new java.lang.ref.WeakReference<>(dialog);java.lang.ref.WeakReference<TextView> stateView=new java.lang.ref.WeakReference<>(status);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{
   if(MemoryIndexService.running){status.setText("Aguarde ou cancele a análise atual antes de salvar a marcação.");return;}final MemoryText.Cue cue;try{cue=MemoryNote.cue(label.getText().toString(),page,from.getText().toString(),to.getText().toString(),limit);}catch(IllegalArgumentException error){status.setText(error.getMessage());return;}
   dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);status.setText("Salvando marcação…");worker.execute(()->{try{try(ParcelFileDescriptor read=app.getContentResolver().openFileDescriptor(uri,"r")){if(read==null||read.getStatSize()==0)throw new java.io.IOException("O arquivo não está acessível para criar a marcação.");}MemoryStore.Source source=MemoryStore.source(app,uri,null,title==null?"Arquivo":title,kind);try(MemoryStore store=new MemoryStore(app)){store.note(source,cue);}main.post(()->{Activity a=host.get();AlertDialog d=weak.get();if(a!=null&&!a.isDestroyed()&&d!=null&&d.isShowing()){d.dismiss();Toast.makeText(a,"Marcação salva na Memória Multimídia • trechos favoritos",Toast.LENGTH_LONG).show();}});}catch(Exception error){main.post(()->{Activity a=host.get();AlertDialog d=weak.get();TextView view=stateView.get();if(a!=null&&!a.isDestroyed()&&d!=null&&d.isShowing()&&view!=null){d.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);view.setText(error.getMessage()==null?"Não foi possível salvar. Confira o acesso ao arquivo.":error.getMessage());}});}});
  });return dialog;
 }
}
